import { Component, OnInit } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { CommonModule } from '@angular/common';
import { Solicitud } from '../../../models/solicitud.model';
import { SolicitudService } from '../../../controllers/solicitud.service';

@Component({
  selector: 'app-solicitud-detail',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './solicitud-detail.html',
  styleUrl: './solicitud-detail.css'
})
export class SolicitudDetailComponent implements OnInit {
  solicitud: Solicitud | undefined;
  isLoading = true;

  constructor(
    private route: ActivatedRoute,
    private solicitudService: SolicitudService
  ) { }

  ngOnInit(): void {
    this.route.paramMap.subscribe(params => {
      const id = params.get('id');
      if (id) {
        this.solicitudService.find(+id, {
          relations: [
            'municipio',
            'giro_principal',
            'asociacion',
            'niveles_gobierno',
            'limitantes_sitio_web',
            'problemas_regulacion',
            'problemas_tramite',
            'limitantes_mercado',
            'archivos'
          ]
        }).then(solicitud => {
          this.solicitud = solicitud;
          this.isLoading = false;
        });
      }
    });
  }

  downloadFile(archivoId: number, fileName: string): void {
    if (this.solicitud && this.solicitud.id) {
      this.solicitudService.downloadArchivo(this.solicitud.id, archivoId).subscribe(
        (blob: Blob) => {
          const downloadUrl = window.URL.createObjectURL(blob);
          const link = document.createElement('a');
          link.href = downloadUrl;
          link.download = fileName;
          document.body.appendChild(link);
          link.click();
          document.body.removeChild(link);
          window.URL.revokeObjectURL(downloadUrl);
        },
        error => {
          console.error('Error downloading file:', error);
          // Handle error, e.g., show a toast notification
        }
      );
    }
  }
}
